function newGame(){game={level:1,steps:0,gold:0,supplies:3,heading:1,player:{x:1,y:1},floor:makeFloor(1),heroes:[{name:names[0],role:roles[0],hp:42,max:42,mp:6,maxmp:6,power:8,alive:true},{name:names[1],role:roles[1],hp:38,max:38,mp:9,maxmp:9,power:6,alive:true},{name:names[2],role:roles[2],hp:29,max:29,mp:18,maxmp:18,power:5,alive:true},{name:names[3],role:roles[3],hp:32,max:32,mp:10,maxmp:10,power:7,alive:true}],logs:[],encounterCount:0,explored:0,seed:Date.now()};battle=null;turnBusy=false;addLog('The company enters the drowned archive.');addLog('A lost seal waits somewhere on the third level.');$('startOverlay').classList.add('hide');$('endOverlay').classList.add('hide');$('battleOverlay').classList.add('hide');updateAll();setNarrative('A cold breath stirs the dust ahead.');render()}
function addLog(text){if(!game)return;game.logs.unshift({text,time:game.steps});game.logs=game.logs.slice(0,20);renderLog()}
function setNarrative(text){$('narrative').textContent=text}
function updateAll(){if(!game)return;$('depthLabel').textContent=String(game.level).padStart(2,'0');$('goldLabel').textContent=game.gold;$('supplyLabel').textContent=game.supplies;$('zoneName').textContent=`Lower Archive · Level ${String(game.level).padStart(2,'0')}`;$('depthText').textContent=`Depth ${['I','II','III'][Math.min(2,game.level-1)]||game.level} · ${game.steps} steps`;$('compassArrow').textContent=['▲','▶','▼','◀'][game.heading];$('partyCount').textContent=`${game.heroes.filter(h=>h.hp>0).length} souls`;renderParty();renderLog();drawMap()}
function renderParty(){let list=$('partyList');list.innerHTML='';game.heroes.forEach(h=>{let div=document.createElement('div');div.className='hero';let hp=Math.max(0,h.hp);div.innerHTML=`<div class="hero-head"><div><span class="hero-name">${h.name}</span><span class="hero-role">${h.role}</span></div><span class="hero-hp">${hp}<span style="color:#687064"> / ${h.max}</span></span></div><div class="bar"><i style="width:${100*hp/h.max}%;background:${hp/h.max<.28?'#b96859':''}"></i></div><div class="hero-sub"><span>VIGOR</span><span>✧ ${h.mp} / ${h.maxmp} MANA</span><span class="condition">${hp===0?'FALLEN':hp/h.max<.25?'WOUNDED':'READY'}</span></div>`;list.appendChild(div)})}
function renderLog(){if(!game)return;$('logList').innerHTML=game.logs.slice(0,8).map(x=>`<div class="log-line"><span class="time">${String(x.time).padStart(2,'0')}·</span>${x.text}</div>`).join('')}
function drawMap(){if(!game)return;let c=mapCanvas.parentElement,w=Math.max(100,c.clientWidth-16),h=Math.max(80,c.clientHeight-16);mapCanvas.width=w;mapCanvas.height=h;let cell=Math.min(w/game.floor.w,h/game.floor.h),ox=(w-cell*game.floor.w)/2,oy=(h-cell*game.floor.h)/2;mctx.fillStyle='#111713';mctx.fillRect(0,0,w,h);for(let y=0;y<game.floor.h;y++)for(let x=0;x<game.floor.w;x++){if(!game.floor.seen[y][x])continue;let wall=game.floor.grid[y][x]===1;mctx.fillStyle=wall?'#394039':'#7a8069';mctx.globalAlpha=wall?.62:.7;mctx.fillRect(ox+x*cell,oy+y*cell,Math.ceil(cell-.8),Math.ceil(cell-.8));mctx.globalAlpha=1;let f=game.floor.features[`${x},${y}`];if(f){mctx.fillStyle=f==='chest'?'#d0a356':'#a0b7a0';mctx.fillRect(ox+(x+.32)*cell,oy+(y+.32)*cell,cell*.36,cell*.36)}if(x===game.floor.stairs.x&&y===game.floor.stairs.y){mctx.fillStyle='#d5c078';mctx.fillRect(ox+(x+.25)*cell,oy+(y+.25)*cell,cell*.5,cell*.5)}}let p=game.player;mctx.fillStyle='#e2bd70';mctx.beginPath();mctx.arc(ox+(p.x+.5)*cell,oy+(p.y+.5)*cell,Math.max(2,cell*.32),0,Math.PI*2);mctx.fill();let[dx,dy]=directions[game.heading];mctx.strokeStyle='#e2bd70';mctx.lineWidth=1.5;mctx.beginPath();mctx.moveTo(ox+(p.x+.5)*cell,oy+(p.y+.5)*cell);mctx.lineTo(ox+(p.x+.5+dx*.7)*cell,oy+(p.y+.5+dy*.7)*cell);mctx.stroke()}
function resize(){let r=scene.getBoundingClientRect();if(!r.width||!r.height)return;scene.width=Math.floor(r.width*Math.min(1.25,devicePixelRatio||1));scene.height=Math.floor(r.height*Math.min(1.25,devicePixelRatio||1));if(game)render()}
function render(){if(!game)return;let W=scene.width,H=scene.height;if(!W||!H)return;ctx.fillStyle='#111814';ctx.fillRect(0,0,W,H);let horizon=H*.49;
let ceil=ctx.createLinearGradient(0,0,0,horizon);ceil.addColorStop(0,'#101715');ceil.addColorStop(1,'#28332d');ctx.fillStyle=ceil;ctx.fillRect(0,0,W,horizon);
let floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#34392e');floor.addColorStop(.33,'#20271f');floor.addColorStop(1,'#101612');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
// Receding flagstones, converging on the vanishing point.
ctx.strokeStyle='#a1a18218';ctx.lineWidth=1;for(let i=1;i<10;i++){let y=horizon+(H-horizon)*i*i/100;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let i=-5;i<=5;i++){ctx.beginPath();ctx.moveTo(W/2+i*W*.035,horizon);ctx.lineTo(W/2+i*W*.22,H);ctx.stroke()}
let px=game.player.x+.5,py=game.player.y+.5,ang=game.heading*Math.PI/2,fov=Math.PI/3,step=2;
for(let sx=0;sx<W;sx+=step){let camera=(sx/W-.5),rayAng=ang+Math.atan(camera*1.12),rx=Math.cos(rayAng),ry=Math.sin(rayAng),mx=Math.floor(px),my=Math.floor(py),ddx=Math.abs(1/rx),ddy=Math.abs(1/ry),sxstep=rx<0?-1:1,systep=ry<0?-1:1,sdx=(rx<0?px-mx:mx+1-px)*ddx,sdy=(ry<0?py-my:my+1-py)*ddy,side=0,hit=0,dist=0;
for(let n=0;n<40&&!hit;n++){if(sdx<sdy){sdx+=ddx;mx+=sxstep;side=0}else{sdy+=ddy;my+=systep;side=1}if(mx<0||my<0||mx>=game.floor.w||my>=game.floor.h||game.floor.grid[my][mx]===1){hit=1;dist=side===0?sdx-ddx:sdy-ddy}}
dist=Math.max(.08,dist*Math.cos(rayAng-ang));let wallH=Math.min(H*1.5,H*.82/dist),top=horizon-wallH*.5,bottom=horizon+wallH*.5;let wallX=side===0?py+dist*ry:px+dist*rx;wallX-=Math.floor(wallX);let tone=(side===1?.7:1)*Math.max(.22,1-dist/11),base=[74,82,69];let c=`rgb(${Math.floor(base[0]*tone)},${Math.floor(base[1]*tone)},${Math.floor(base[2]*tone)})`;ctx.fillStyle=c;ctx.fillRect(sx,top,step+1,wallH);
// Aged blockwork with irregular mortar and salt streaks.
let brick=Math.floor(wallX*8),local=wallX*8-brick,rows=Math.max(1,Math.floor(wallH/21));for(let j=1;j<rows;j++){let yy=top+wallH*j/rows;if(yy>top&&yy<bottom){ctx.fillStyle=`rgba(13,20,16,${.18+((brick+j)%3)*.035})`;ctx.fillRect(sx,yy,step+1,1)}}if(local<.04||local>.96){ctx.fillStyle=`rgba(8,13,11,${.28*tone})`;ctx.fillRect(sx,top,1,wallH)}
if(dist>1.3&&dist<5&&Math.abs(camera)<.22&&((mx*7+my*3)%11===0)){let glow=Math.max(0,1-dist/6),gy=horizon-wallH*.32;ctx.fillStyle=`rgba(229,161,75,${glow*.2})`;ctx.beginPath();ctx.arc(sx,gy,Math.max(2,wallH*.04),0,Math.PI*2);ctx.fill()}
}

