function showToast(text){let el=document.createElement('div');el.className='toast';el.textContent=text;$('toastHolder').appendChild(el);setTimeout(()=>el.remove(),2500)}
const foes=[{name:'Archive Wight',art:'☠',desc:'A thing made of old ink and colder hunger.',hp:36,attack:6,xp:16},{name:'Siltfang',art:'♞',desc:'A pale, blind hunter swims through the air.',hp:30,attack:7,xp:14},{name:'Mirebound Acolyte',art:'♆',desc:'Its drowned robes whisper a prayer in reverse.',hp:43,attack:5,xp:21},{name:'Ashen Sentinel',art:'♜',desc:'A rusted guardian still keeps its ancient watch.',hp:55,attack:8,xp:26}];
function startBattle(){if(battle)return;let base=foes[Math.min(foes.length-1,Math.floor(Math.random()*(game.level+1)))];battle={...base,max:base.hp+game.level*8,hp:base.hp+game.level*8,attack:base.attack+game.level-1};battle.max=battle.hp;game.encounterCount++;$('enemyName').textContent=battle.name;$('enemyArt').textContent=battle.art;$('enemyDesc').textContent=battle.desc;$('battleKicker').textContent=`Encounter ${String(game.encounterCount).padStart(2,'0')} · level ${game.level}`;$('battleReport').textContent='The enemy blocks the way. Choose your action.';$('battleOverlay').classList.remove('hide');setNarrative(`${battle.name} lurches from the darkness!`);addLog(`${battle.name} blocks the passage.`);drawBattle();render()}
function drawBattle(){$('enemyHpBar').style.width=`${Math.max(0,100*battle.hp/battle.max)}%`;$('enemyHpText').textContent=`${Math.max(0,battle.hp)} / ${battle.max}`;document.querySelector('[data-battle="spell"]').disabled=!game.heroes.some(h=>h.hp>0&&h.mp>=3);document.querySelector('[data-battle="potion"]').disabled=game.supplies<1||!game.heroes.some(h=>h.hp<h.max)}
function battleAction(action){if(!battle||turnBusy)return;let report='',living=game.heroes.filter(h=>h.hp>0);if(!living.length)return;
if(action==='flee'){if(Math.random()<.54){$('battleOverlay').classList.add('hide');addLog('The company slips away from the encounter.');setNarrative('You retreat into the winding dark.');battle=null;updateAll();render();return}else report='There is no escape! ';}
else if(action==='attack'){let total=0;living.forEach(h=>{let d=Math.max(2,Math.floor(h.power*(.72+Math.random()*.72)));total+=d});battle.hp-=total;report=`The company strikes together for ${total} damage.`}
else if(action==='spell'){let casters=living.filter(h=>h.mp>=3),total=0;if(!casters.length){$('battleReport').textContent='No one has enough mana.';return}casters.forEach(h=>{h.mp-=3;total+=Math.floor(10+Math.random()*9+game.level*2)});battle.hp-=total;report=`Ember magic sears the foe for ${total} damage.`}
else if(action==='guard'){game.guarding=true;report='Shields lock together. Brace for the counterattack.'}
else if(action==='potion'){if(game.supplies<1){$('battleReport').textContent='No tonics remain.';return}let target=living.slice().sort((a,b)=>a.hp/a.max-b.hp/b.max)[0];target.hp=Math.min(target.max,target.hp+24);game.supplies--;report=`A tonic restores ${target.name}'s strength.`}
$('battleReport').textContent=report;drawBattle();renderParty();updateAll();if(battle.hp<=0){winBattle();return}turnBusy=true;setTimeout(()=>{if(!battle)return;let n=Math.random()<.26&&living.length>1?2:1,lines=[];for(let i=0;i<n;i++){let targets=game.heroes.filter(h=>h.hp>0);if(!targets.length)break;let t=targets[Math.floor(Math.random()*targets.length)],d=battle.attack+Math.floor(Math.random()*5);if(game.guarding)d=Math.ceil(d*.42);t.hp=Math.max(0,t.hp-d);lines.push(`${t.name} takes ${d} damage`)}game.guarding=false;$('battleReport').textContent=lines.join(' · ')||'The foe lashes out.';addLog(lines.join('; ')||'The foe attacks.');turnBusy=false;renderParty();updateAll();if(!game.heroes.some(h=>h.hp>0)){setTimeout(()=>endGame(false),450)}else drawBattle()},530)}
function winBattle(){let defeated=battle.name,earned=battle.xp+Math.floor(Math.random()*8),coin=5+Math.floor(Math.random()*12);game.gold+=coin;game.heroes.forEach(h=>{if(h.hp>0)h.hp=Math.min(h.max,h.hp+2)});battle=null;$('battleOverlay').classList.add('hide');addLog(`${defeated} is banished. Found ${coin} gold.`);setNarrative(`${defeated} dissolves into a drifting cloud of ash.`);showToast(`VICTORY · +${earned} RENOWN · +${coin} GOLD`);updateAll();render()}
function endGame(victory){$('battleOverlay').classList.add('hide');$('endOverlay').classList.remove('hide');if(victory){$('endKicker').textContent='The Lost Seal is restored';$('endTitle').textContent='Dawn remembers';$('endText').textContent=`The seal is set into its ancient lock. Light spills into the archive, and your company emerges with ${game.gold} gold and ${game.encounterCount} victories. Ashenhold will remember your names.`}else{$('endKicker').textContent='The archive claims its due';$('endTitle').textContent='Lost to the deep';$('endText').textContent=`The company fell on level ${game.level}, ${game.gold} gold still in its packs. The drowned stacks grow quiet again. Every descent remakes the labyrinth.`}}
function useTonic(){if(battle){battleAction('potion');return}if(game.supplies<1){showToast('NO TONICS LEFT');return}let target=game.heroes.filter(h=>h.hp>0&&h.hp<h.max).sort((a,b)=>a.hp/a.max-b.hp/b.max)[0];if(!target){showToast('THE COMPANY IS UNWOUNDED');return}target.hp=Math.min(target.max,target.hp+24);game.supplies--;addLog(`A tonic restores ${target.name}.`);setNarrative(`${target.name} drinks a restorative tonic.`);updateAll()}
function castEmber(){if(battle){battleAction('spell');return}let hero=game.heroes.find(h=>h.hp>0&&h.mp>=3);if(!hero){showToast('NO MANA TO SPARE');return}hero.mp-=3;let[dX,dY]=directions[game.heading],x=game.player.x+dX,y=game.player.y+dY;if(wall(x,y)){setNarrative('Emberlight splashes harmlessly across the stone.');addLog(`${hero.name}'s ember fizzles against a wall.`)}else if(Math.random()<.38){let g=4+Math.floor(Math.random()*7);game.gold+=g;setNarrative('The flame reveals a glimmer beneath the silt.');addLog(`Emberlight uncovers ${g} old coins.`)}else{setNarrative('A ribbon of ember magic coils into the dark.');addLog(`${hero.name} casts emberlight; nothing stirs.`)}updateAll();render()}
function rest(){if(battle)return;let hurt=game.heroes.some(h=>h.hp>0&&h.hp<h.max);if(!hurt){showToast('NO ONE NEEDS REST');return}let healed=0;game.heroes.forEach(h=>{if(h.hp>0){let a=Math.min(8,h.max-h.hp);h.hp+=a;healed+=a;h.mp=Math.min(h.maxmp,h.mp+2)}});game.steps+=2;setNarrative('The company rests beneath a watchful hush.');addLog(`A brief rest restores ${healed} vigor.`);updateAll();render();if(Math.random()<.18)startBattle()}

