    response=sock.recv(4096)
    if b'101' not in response.split(b'\r\n',1)[0]: raise RuntimeError(response[:300])
    buf=b''; msgid=0
    def recvmsg():
        global buf
        while len(buf)<2: buf+=sock.recv(65536)
        a,b=buf[0],buf[1]; n=b&127; pos=2
        if n==126:
            while len(buf)<4: buf+=sock.recv(65536)
            n=struct.unpack('!H',buf[2:4])[0];pos=4
        elif n==127:
            while len(buf)<10: buf+=sock.recv(65536)
            n=struct.unpack('!Q',buf[2:10])[0];pos=10
        if b&128:
            while len(buf)<pos+4+n: buf+=sock.recv(65536)
            mask=buf[pos:pos+4];pos+=4
        else:
            while len(buf)<pos+n: buf+=sock.recv(65536)
            mask=None
        data=buf[pos:pos+n];buf=buf[pos+n:]
        if mask:data=bytes(x^mask[i%4] for i,x in enumerate(data))
        return json.loads(data)
    def sendmsg(obj):
        data=json.dumps(obj).encode();mask=b'\x11\x22\x33\x44';n=len(data)
        hdr=bytes([0x81,0x80|(n if n<126 else 126)])+(struct.pack('!H',n) if 126<=n<65536 else b'')
        if n>=65536: raise ValueError('frame too long')
        sock.sendall(hdr+mask+bytes(x^mask[i%4] for i,x in enumerate(data)))
    def command(method,params=None):
        global msgid
        msgid+=1; sendmsg({'id':msgid,'method':method,'params':params or {}})
        while True:
            r=recvmsg()
            if r.get('id')==msgid:
                if 'error' in r: raise RuntimeError(r['error'])
                return r.get('result',{})
    time.sleep(.8)
    state=command('Runtime.evaluate',{'expression':'JSON.stringify({started:document.getElementById("startOverlay").classList.contains("hide"),heroes:document.querySelectorAll(".hero").length,steps:document.getElementById("depthText").textContent,arrow:document.getElementById("compassArrow").textContent,errors:document.body.dataset.test})','returnByValue':True})
